// Package webassets serves the compiled shared web shell. The committed dist
// tree is generated by frontend/check_build.py from the frontend sources; no
// development server is involved. The unit test verifies the recorded manifest
// and recomputes the frontend input digest so source-only edits cannot pass
// the canonical gate without regenerating dist.
package webassets

import (
	"embed"
	"io/fs"
)

//go:embed all:dist
var embedded embed.FS

// Dist returns the committed compiled shell assets.
func Dist() fs.FS {
	sub, err := fs.Sub(embedded, "dist")
	if err != nil {
		// The embedded tree always contains dist; failing here is a build error.
		panic(err)
	}
	return sub
}

// Index returns the shell HTML document.
func Index() ([]byte, error) {
	return fs.ReadFile(Dist(), "index.html")
}
